<?php
require_once __DIR__.'/includes/bootstrap.php';$error='';$edit=null;
if(isset($_GET['edit'])){require_login();$id=(int)$_GET['edit'];$s=db()->prepare('SELECT * FROM events WHERE event_id=?');$s->execute([$id]);$edit=$s->fetch();if(!$edit||!can_manage_club((int)$edit['club_id'])){flash('error','You cannot manage that event.');redirect('events.php');}}
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();$action=$_POST['action']??'';
if($action==='delete'){$id=(int)$_POST['event_id'];$s=db()->prepare('SELECT club_id FROM events WHERE event_id=?');$s->execute([$id]);$club=(int)$s->fetchColumn();if(!can_manage_club($club)){http_response_code(403);exit('Not authorized.');}db()->prepare('DELETE FROM events WHERE event_id=?')->execute([$id]);flash('success','Event deleted.');redirect('events.php');}
if($action==='cancel'){$id=(int)$_POST['event_id'];$s=db()->prepare('SELECT club_id FROM events WHERE event_id=?');$s->execute([$id]);$club=(int)$s->fetchColumn();if(!can_manage_club($club)){http_response_code(403);exit('Not authorized.');}db()->prepare("UPDATE events SET status='Cancelled' WHERE event_id=?")->execute([$id]);flash('success','Event cancelled.');redirect('events.php');}
if($action==='save'){$id=(int)($_POST['event_id']??0);$club=(int)($_POST['club_id']??0);if(!can_manage_club($club)){http_response_code(403);exit('Not authorized.');}$title=trim($_POST['title']??'');$date=$_POST['event_date']??'';$deadline=$_POST['registration_deadline']??'';$max=(int)($_POST['maximum_participants']??0);if($title===''||!$date||$max<1||($deadline&&$deadline>$date)){$error='Enter a title and valid dates. Capacity must be greater than zero, and the deadline cannot follow the event date.';}else{$values=[$club,(int)user()['user_id'],$title,trim($_POST['description']??''),trim($_POST['event_category']??''),$date,$_POST['start_time']??null,$_POST['end_time']??null,trim($_POST['venue']??''),$max,$deadline?:null,$_POST['status']??'Draft'];if($id){$s=db()->prepare('SELECT club_id FROM events WHERE event_id=?');$s->execute([$id]);if(!can_manage_club((int)$s->fetchColumn())){http_response_code(403);exit('Not authorized.');}$values[]=$id;db()->prepare('UPDATE events SET club_id=?,created_by_user_id=?,title=?,description=?,event_category=?,event_date=?,start_time=?,end_time=?,venue=?,maximum_participants=?,registration_deadline=?,status=? WHERE event_id=?')->execute($values);flash('success','Event updated.');}else{db()->prepare('INSERT INTO events (club_id,created_by_user_id,title,description,event_category,event_date,start_time,end_time,venue,maximum_participants,registration_deadline,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')->execute($values);flash('success','Event created.');}redirect('events.php');}}}
$manageable=[];if(user()){if(is_admin()){$manageable=db()->query("SELECT club_id,club_name FROM clubs WHERE status='Active' ORDER BY club_name")->fetchAll();}else{$marks=implode(',',array_fill(0,count(executive_roles()),'?'));$s=db()->prepare("SELECT c.club_id,c.club_name FROM club_membership cm JOIN clubs c ON c.club_id=cm.club_id WHERE cm.student_user_id=? AND cm.approval_status='Approved' AND cm.membership_status='Active' AND cm.member_role IN ($marks)");$s->execute(array_merge([(int)user()['user_id']],executive_roles()));$manageable=$s->fetchAll();}}
$events=db()->query("SELECT e.*,c.club_name,COUNT(er.registration_id) registration_count FROM events e JOIN clubs c ON c.club_id=e.club_id LEFT JOIN event_registration er ON er.event_id=e.event_id AND er.registration_status='Registered' GROUP BY e.event_id ORDER BY e.event_date,e.start_time")->fetchAll();$pageTitle='Events';require __DIR__.'/includes/header.php';?>
<section class="page-shell"><div class="page-head"><div><span class="eyebrow">What’s happening</span><h2>Events worth showing up for</h2><p>Discover upcoming activities from clubs across campus.</p></div><?php if($manageable):?><a class="button button-primary" href="events.php?new=1">Create event</a><?php endif;?></div>
<?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?>
<?php if((isset($_GET['new'])&&$manageable)||$edit):?><form class="card" method="post" style="margin-bottom:30px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="event_id" value="<?=e((string)($edit['event_id']??''))?>"><h3><?=$edit?'Edit event':'Create an event'?></h3><div class="field-grid"><div class="field"><label>Club</label><select name="club_id" required><?php foreach($manageable as $c):?><option value="<?=$c['club_id']?>" <?=(int)($edit['club_id']??0)===(int)$c['club_id']?'selected':''?>><?=e($c['club_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Title</label><input name="title" required value="<?=e($edit['title']??'')?>"></div><div class="field"><label>Category</label><input name="event_category" required value="<?=e($edit['event_category']??'')?>"></div><div class="field"><label>Venue</label><input name="venue" required value="<?=e($edit['venue']??'')?>"></div><div class="field"><label>Event date</label><input name="event_date" type="date" required value="<?=e($edit['event_date']??'')?>"></div><div class="field"><label>Registration deadline</label><input name="registration_deadline" type="date" value="<?=e($edit['registration_deadline']??'')?>"></div><div class="field"><label>Start time</label><input name="start_time" type="time" value="<?=e($edit['start_time']??'')?>"></div><div class="field"><label>End time</label><input name="end_time" type="time" value="<?=e($edit['end_time']??'')?>"></div><div class="field"><label>Maximum participants</label><input name="maximum_participants" type="number" min="1" required value="<?=e((string)($edit['maximum_participants']??50))?>"></div><div class="field"><label>Status</label><select name="status"><?php foreach(['Draft','Upcoming','Ongoing','Completed','Cancelled'] as $st):?><option <?=$st===($edit['status']??'Draft')?'selected':''?>><?=e($st)?></option><?php endforeach;?></select></div></div><div class="field"><label>Description</label><textarea name="description" required><?=e($edit['description']??'')?></textarea></div><button class="button button-primary">Save event</button> <a class="button button-quiet" href="events.php">Cancel</a></form><?php endif;?>
<div class="grid"><?php foreach($events as $event):?><article class="card"><span class="card-tag"><?=e($event['event_category'])?></span><h3><?=e($event['title'])?></h3><p class="muted"><?=e($event['description'])?></p><div class="detail-list"><span><strong><?=e(date('M j, Y',strtotime($event['event_date'])))?></strong> · <?=e(substr((string)$event['start_time'],0,5))?></span><span><?=e($event['venue'])?> · <?=e($event['club_name'])?></span><span><?= (int)$event['registration_count']?> / <?= (int)$event['maximum_participants']?> registered</span></div><div class="card-footer"><span class="badge <?=$event['status']==='Cancelled'?'badge-danger':''?>"><?=e($event['status'])?></span><?php if(user()&&can_manage_club((int)$event['club_id'])):?><div class="actions"><a class="button button-quiet" href="events.php?edit=<?=$event['event_id']?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="event_id" value="<?=$event['event_id']?>"><?php if($event['status']!=='Cancelled'):?><button class="button button-danger" name="action" value="cancel" data-confirm="Cancel this event?">Cancel</button><?php endif;?><button class="button button-danger" name="action" value="delete" data-confirm="Permanently delete this event?">Delete</button></form></div><?php endif;?></div></article><?php endforeach;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
